-- Bereits beauftragter HRT für den konkreten Verein; keine Antwort-/Friständerung bestehender Tests.
insert into private.hausregeltests(verein_id,kennung,titel,fragen,vorbereitung_bis,endfassung_ab,abgabe_bis,aktiv)
select v.id,'hrt-1-2026-27','Hausregeltest 1 · 2026/27', '["Ein Ersatzspieler muss wegen eines zu langsam durchgeführten Spielerwechsels eine Minute außerhalb des Feldes warten. Unter welchen Voraussetzungen darf der Spieler das Spielfeld wieder betreten.","Ein Verteidiger spielt den Ball nach vorn. Der Ball trifft den Schiedsrichter und gelangt dadurch zu einem gegnerischen Angreifer. Der Schiedsrichter unterbricht. Wie, wo und mit welcher Mannschaft wird das Spiel fortgesetzt?","Nach einer Verletzungsbehandlung auf dem Feld setzt ein Spieler die Versorgung außerhalb fort. Eine Minute ist vergangen. Er bittet um Rückkehr, während der Ball weit entfernt gespielt wird und er nicht unmittelbar eingreifen kann. Muss der Schiedsrichter eine Spielunterbrechung abwarten? Was ist für seine Rückkehr erforderlich?","Ein Angreifer läuft allein auf das Tor zu. Rund 25 Meter davor reißt ihn ein Verteidiger um und verhindert damit eine offensichtliche Torchance. Der Schiedsrichter lässt Vorteil gelten. Ein weiterer Angreifer übernimmt den Ball und erzielt nach wenigen Metern ein Tor. Welche Spielfortsetzung und welche persönliche Strafe sind richtig?","Bei einem Abstoß verzögert der Torhüter die Ausführung. Der Schiedsrichter zeigt mit erhobenem Arm den Fünf-Sekunden-Countdown an. Auch nach dessen Ablauf ist der Ball nicht im Spiel. Welche Spielfortsetzung erfolgt und von welcher Seite?","Bei einem Einwurf hebt der Werfer einen Fuß bereits vor dem Loslassen des Balls deutlich an. Der Ball berührt zunächst außerhalb des Feldes den Boden und rollt erst anschließend hinein. Ein Gegner nimmt ihn auf und könnte aussichtsreich angreifen. Wie entscheidet der Schiedsrichter? Begründe.","Ein Spieler verlässt nach einer Verletzungsbehandlung das Spielfeld. Seine Mannschaft möchte ihn unmittelbar durch einen Ersatzspieler ersetzen. Darf dieser sofort mitspielen oder muss er eine Minute warten? Begründe.","Ein Spieler führt einen Eckstoß trotz Aufforderung weiterhin nicht aus. Der Schiedsrichter zählt fünf Sekunden herunter und entscheidet danach auf Abstoß, ohne den Spieler zu verwarnen. Wie hätte er richtig entscheiden müssen?","Bei einem Strafstoß rutscht der Schütze aus. Nach dem Schuss berührt der Ball unabsichtlich noch sein Standbein und fliegt anschließend direkt ins Tor. Der Torhüter hat sich regelkonform verhalten. Wie entscheidet der Schiedsrichter? Begründe.","Ein Flügelspieler dribbelt auf der linken Seite und will eine Flanke vorbereiten. Sein zentraler Mitspieler läuft sich frei, steht nicht im Abseits und hat den Ball noch nicht erhalten. Bevor die Flanke gespielt wird, stellt ihm ein Verteidiger knapp außerhalb des Strafraums in unsportlicher Absicht ein Bein. Damit unterbindet er eine gute Angriffssituation mit zu erwartendem Zuspiel. Welche Spielfortsetzung und persönliche Strafe folgen?"]'::jsonb,
'2026-11-09T00:00:00+01:00'::timestamptz,'2026-11-09T00:00:00+01:00'::timestamptz,'2026-11-23T00:00:00+01:00'::timestamptz,true
from public.vereine v where v.id='f48b8b1c-53d8-49f9-80b7-02e8848b7fb8' and v.name='Löbtauer Kickers'
on conflict(verein_id,kennung) do nothing;
